css=r'''
june-footer.jfooter{display:block;max-width:1680px;margin:auto;padding:36px 52px 20px;background:var(--jfooter-bg);color:var(--jfooter-ink)}.jfooter *{box-sizing:border-box}.jfooter h2,.jfooter p{margin:0;color:inherit}.jfooter a{color:inherit;text-decoration:none}.jfooter a:hover{text-decoration:underline;text-underline-offset:4px}.jfooter button,.jfooter input,.jfooter select{font:inherit}.jfooter a:focus-visible,.jfooter summary:focus-visible,.jfooter button:focus-visible,.jfooter input:focus-visible,.jfooter select:focus-visible{outline:2px solid var(--jfooter-ink);outline-offset:4px}.jfooter summary{cursor:pointer;list-style:none}.jfooter summary::-webkit-details-marker{display:none}
ROLES
.jfooter__top{display:flex;align-items:center;justify-content:space-between;gap:30px;padding-bottom:26px;border-bottom:1px solid var(--jfooter-ink)}.jfooter__top .jfooter__heading{max-width:900px}.jfooter__social{display:flex;align-items:center;gap:10px;flex:none;min-height:44px}.jfooter__arrow{display:grid;place-items:center;width:24px;height:24px;flex:none;border-radius:50%;background:#111;color:var(--jfooter-accent)}.jfooter__arrow svg{width:16px;height:16px}.jfooter__middle{display:grid;grid-template-columns:1fr 1fr 1.15fr 1.4fr;gap:32px;padding:30px 0;border-bottom:1px solid var(--jfooter-ink)}.jfooter__group summary{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;pointer-events:none}.jfooter__group summary span{display:none}.jfooter__links{display:flex;flex-direction:column}.jfooter__links a{display:flex;align-items:center;min-height:36px;padding:4px 0;overflow-wrap:anywhere}.jfooter__aside{border-left:1px solid var(--jfooter-ink);padding-left:32px}.jfooter__aside>.jfooter__title{font-size:calc(var(--jfooter-title-size)*1.2);margin-bottom:16px}.jfooter__back{display:inline-flex;align-items:center;gap:10px;min-height:44px;text-decoration:underline!important;text-underline-offset:5px}.jfooter__newsletter{margin-top:10px}.jfooter__newsletter>summary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;border-top:1px solid #1114}.jfooter__newsletter[open]>summary>span{transform:rotate(45deg)}.jfooter__form label{display:block;margin:12px 0 6px}.jfooter .jfooter__email{width:100%;min-height:46px;background:transparent;color:inherit;border:1px solid #1118;border-radius:3px;padding:10px;font-size:16px}.jfooter .jfooter__primary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:50px;width:100%;padding:8px 9px 8px 20px;border:1px solid #111;border-radius:999px;background:var(--jfooter-accent);color:#111;box-shadow:-2px 1px 0 #111;margin-top:12px;cursor:pointer}.jfooter__primary{transition:transform var(--jfooter-duration) ease}@media(hover:hover){.jfooter[data-motion=true] .jfooter__primary:hover{transform:translateY(-2px)}}@media(prefers-reduced-motion:reduce){.jfooter .jfooter__primary{transition:none!important;transform:none!important}}.jfooter[data-motion=false] .jfooter__primary{transition:none}.jfooter__primary .jfooter__arrow{width:32px;height:32px}.jfooter .jfooter__note{font-size:12px;margin-top:10px}.jfooter__mobile-actions{display:none}
.jfooter__brand{font-family:var(--jfooter-brand-font);font-weight:var(--jfooter-brand-weight);font-size:clamp(40px,10.4vw,var(--jfooter-brand-size));letter-spacing:var(--jfooter-brand-tracking);line-height:var(--jfooter-brand-leading);padding:22px 0 18px;text-transform:uppercase;overflow-wrap:anywhere}.jfooter__brand>span{color:var(--jfooter-accent)}.jfooter__bottom{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:12px!important}.jfooter__legal{display:flex;gap:20px}.jfooter__legal a{min-height:44px;display:flex;align-items:center}.jfooter__payments{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px;margin-top:8px}.jfooter__payments svg{width:36px;height:23px}.jfooter__localization{display:flex;gap:8px;max-width:100%}.jfooter__localization select{min-width:0;max-width:210px}.jfooter__localization select,.jfooter__localization button{padding:9px;background:transparent;border:1px solid #1114;border-radius:3px;color:inherit}.jfooter__sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1100px) and (min-width:750px){june-footer.jfooter{padding:30px}.jfooter__middle{gap:20px}.jfooter__aside{padding-left:20px}.jfooter__top .jfooter__heading{font-size:calc(var(--jfooter-heading-size)*.8)}}
@media(max-width:749px){june-footer.jfooter{padding:28px 24px 18px}.jfooter .jfooter__heading{font-size:var(--jfooter-heading-mobile)}.jfooter .jfooter__title{font-size:var(--jfooter-title-mobile)}.jfooter .jfooter__body{font-size:var(--jfooter-body-mobile)}.jfooter .jfooter__button-type{font-size:var(--jfooter-button-mobile)}.jfooter__top{padding-bottom:22px}.jfooter__social{display:none}.jfooter__middle{display:block;padding:0;border-bottom:0}.jfooter__group{border-bottom:1px solid #1115}.jfooter__group summary{min-height:62px;margin:0;pointer-events:auto}.jfooter__group summary span{display:block;font-weight:400;font-size:25px}.jfooter__group[open] summary span{transform:rotate(45deg)}.jfooter__links{padding-bottom:14px}.jfooter__links a{min-height:44px}.jfooter__aside{border:0;padding:0}.jfooter__aside>.jfooter__title,.jfooter__aside>.jfooter__back{display:none}.jfooter__newsletter{margin:0}.jfooter__newsletter>summary{border-top:0;border-bottom:1px solid #1115;min-height:56px}.jfooter__form{padding-bottom:18px}.jfooter__mobile-actions{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--jfooter-ink);padding:10px 0}.jfooter__mobile-actions a{display:flex;align-items:center;gap:8px;min-height:44px}.jfooter__brand{font-size:min(var(--jfooter-brand-mobile),14.2vw);padding:22px 0 14px;max-width:100%}.jfooter__bottom{gap:4px 14px}.jfooter__payments{justify-content:flex-start}.jfooter .jfooter__note{font-size:12px}.jfooter__localization{flex-wrap:wrap}}
'''.replace('ROLES',roles)
js=r'''
if(!customElements.get('june-footer'))customElements.define('june-footer',class extends HTMLElement{
 connectedCallback(){this.controller?.abort();this.controller=new AbortController();const signal=this.controller.signal;this.media=matchMedia('(min-width:750px)');const sync=()=>this.querySelectorAll('.jfooter__group').forEach(g=>{g.open=this.media.matches;g.querySelector('summary').tabIndex=this.media.matches?-1:0;});sync();this.media.addEventListener('change',sync,{signal});this.addEventListener('click',e=>{const top=e.target.closest('[data-top]');if(top){e.preventDefault();window.scrollTo({top:0,behavior:this.dataset.motion==='true'&&!matchMedia('(prefers-reduced-motion:reduce)').matches?'smooth':'instant'});const target=[...document.querySelectorAll('h1')].find(el=>el.getClientRects().length&&!el.closest('[hidden],[inert]'))||document.querySelector('main')||document.body;const old=target.getAttribute('tabindex');target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.addEventListener('blur',()=>{if(old===null)target.removeAttribute('tabindex');else target.setAttribute('tabindex',old);},{once:true});}if(this.media.matches&&e.target.closest('.jfooter__group>summary'))e.preventDefault();},{signal});if(this.querySelector('.jfooter__form [role=status],.jfooter__form [role=alert]'))this.querySelector('.jfooter__newsletter').open=true;this.addEventListener('shopify:block:select',e=>{const d=e.target.closest('.jfooter__group');if(d)d.open=true;},{signal});}
 disconnectedCallback(){this.controller?.abort();}
});
'''
