settings=[text('heading','Heading','A little more June, every day.'),text('brand_name','Wordmark','The June Shop'),text('tagline','Brand statement','For your plans.'),text('tagline_second','Brand statement second line','And everything around them.'),{'type':'url','id':'instagram','label':'Instagram URL'},text('instagram_label','Instagram desktop label','Find us on Instagram'),text('mobile_instagram_label','Instagram mobile label','Instagram'),text('back','Back to top label','Back to top'),{'type':'checkbox','id':'newsletter','label':'Show email signup disclosure','default':True},text('signup_heading','Signup disclosure label','Email updates'),text('email_label','Email label','Email address'),text('subscribe','Subscribe button','Subscribe'),text('success','Signup success','Thanks for joining us.'),text('signup_note','Signup note','Sign up for email updates. Unsubscribe anytime.'),text('copyright','Copyright name','June Retail Private Limited'),text('privacy','Privacy link label','Privacy'),text('terms','Terms link label','Terms'),{'type':'checkbox','id':'payments','label':'Show enabled payment methods','default':True},{'type':'checkbox','id':'localization','label':'Show country/language when available','default':True},text('country_label','Country label','Country / region'),text('language_label','Language label','Language'),text('update','Localization submit','Update'),{'type':'color','id':'background','label':'Background','default':'#FFFBF1'},{'type':'color','id':'ink','label':'Text','default':'#111111'},{'type':'color','id':'accent','label':'Accent and button fill','default':'#D5FF46'},{'type':'font_picker','id':'fallback_font','label':'Fallback font','default':'poppins_n4'},{'type':'checkbox','id':'motion','label':'Enable smooth back to top and button motion','default':True},{'type':'range','id':'speed','label':'Motion speed','min':50,'max':200,'step':10,'default':100,'unit':'%'}]
links=[text('heading','Column heading','Explore'),{'type':'link_list','id':'menu','label':'Menu override','info':'Use an existing menu instead of the six editable links below.'}]
for i in range(1,7):links +=[{'type':'text','id':f'label_{i}','label':f'Link {i} label'},{'type':'url','id':f'url_{i}','label':f'Link {i} destination'}]
schema={'name':'June · The footer','tag':'footer','class':'june-footer-section','enabled_on':{'groups':['footer']},'max_blocks':5,'settings':settings,'blocks':[{'type':'links','name':'Link column','limit':3,'settings':links},typ,brand],'presets':[{'name':'June · The footer','blocks':[{'type':'links'},{'type':'links'},{'type':'links'},{'type':'typography'},{'type':'brand_type'}]}]}
